import sys
def pattern(n):
    return '\n'.join(''.join(chr(65 + j) for j in range(i - 1, -1, -1)) for i in range(n, 0, -1))
def main():
    s = sys.stdin.read().strip()
    if s:
        print(pattern(int(s)))
main()

